// Port of shadcn's `message-scroller.tsx`'s `MessageScrollerButton`. Wraps
// `@shadcn/react/message-scroller`'s `MessageScroller.Button`, a
// `useRender`-based polymorphic trigger that subscribes to the controller's
// scrollable-state store (`useSyncExternalStore`) to compute `active`, and
// scrolls to the given `direction`'s edge on click when active.
//
// SIMPLIFICATION FROM SOURCE: `useRender`'s generic `render` prop (letting a
// caller swap the rendered element/component entirely) has no established
// idiom yet in this registry (grep across every existing port turns up no
// `render=` usage) — this port always renders our `<Button>` component
// directly, matching the SOURCE'S OWN DEFAULT (`render={render ?? <Button
// variant={variant} size={size} />}`) exactly. `type="button"`,
// `inert`/`tabIndex` gating, and the click handler's active-guard +
// `blur()` + direction dispatch are all preserved.
//
// The store subscription itself (`useSyncExternalStore` in the source)
// becomes a `<let>` seeded from the controller's synchronous snapshot and
// kept live via `stateStore.subscribe` in a `<lifecycle>` — Marko's
// reactive-local equivalent of a store subscription hook.
import Button from "../button/button.marko";
import Icon from "../icon/icon.marko";
import type { ButtonVariants } from "../button/variants.ts";
import { cn } from "../../../lib/utils.ts";
import type { MessageScrollerControllerGetter } from "./lib/controller.ts";

export interface Input extends Marko.Input<"button">, Pick<ButtonVariants, "variant" | "size"> {
  /** Controller getter provided by the nearest `<message-scroller-provider>`. */
  controller: MessageScrollerControllerGetter;
  /** Native scroll behavior when clicked. Defaults to "smooth". */
  behavior?: ScrollBehavior;
  /** Transcript edge to scroll toward. Defaults to "end". */
  direction?: "start" | "end";
}

<const/{
  controller,
  behavior = "smooth",
  direction = "end",
  variant = "secondary",
  size = "icon-sm",
  class: className,
  content,
  onClick,
  type,
  tabindex,
  ...rest
}=input/>

// Seeded false: the controller only exists in the browser (calling the getter
// during SSR would create — and then fail to serialize — it), and the store's
// initial scrollable snapshot is all-false anyway. onMount syncs immediately.
<let/active=false/>

<lifecycle
  onMount() {
    const stateStore = controller().stateStore;
    const sync = () => {
      const snapshot = stateStore.getSnapshot();
      active = direction === "start" ? snapshot.start : snapshot.end;
    };
    sync();
    // Marko merges onMount's RETURNED OBJECT into `this` (returning the bare
    // unsubscribe function is silently ignored) — onDestroy reads it back.
    return { unsubscribe: stateStore.subscribe(sync) };
  }
  onDestroy() {
    this.unsubscribe?.();
  }
/>

<Button
  ...rest
  variant=variant
  size=size
  type=(type ?? "button")
  inert=(!active)
  tabindex=(active ? tabindex : -1)
  data-slot="message-scroller-button"
  data-direction=direction
  data-variant=variant
  data-size=size
  data-active=String(active)
  class=cn(
    "absolute inset-s-1/2 -translate-x-1/2 border-border bg-background text-foreground transition-[translate,scale,opacity] duration-200 hover:bg-muted hover:text-foreground data-[active=false]:pointer-events-none data-[active=false]:scale-95 data-[active=false]:opacity-0 data-[active=false]:duration-400 data-[active=false]:ease-[cubic-bezier(0.7,0,0.84,0)] data-[active=true]:translate-y-0 data-[active=true]:scale-100 data-[active=true]:opacity-100 data-[active=true]:ease-[cubic-bezier(0.23,1,0.32,1)] data-[direction=end]:bottom-4 data-[direction=end]:data-[active=false]:translate-y-full data-[direction=start]:top-4 data-[direction=start]:data-[active=false]:-translate-y-full rtl:translate-x-1/2 data-[direction=start]:[&_svg]:rotate-180",
    className,
  )
  // No hand-written parameter annotations: Marko infers `onClick`'s real
  // signature for a <button> (a PointerEvent plus the bound element).
  // Annotating them `MouseEvent`/`HTMLElement` widened away that type and
  // made forwarding to the caller's own onClick a type error.
  onClick(event, target) {
    if (!active) return;

    // Marko types event attrs as `handler | false | undefined` (`false`
    // disables the handler), so this must be a callability check, not `?.` —
    // a consumer passing `onClick=false` would otherwise crash here.
    if (typeof onClick === "function") onClick(event, target);

    if (!event.defaultPrevented) {
      // event.currentTarget is unsupported in Marko's delegated events —
      // the handler's 2nd argument is the element the handler is bound to.
      target?.blur();

      if (direction === "start") {
        controller().scrollToStart({ behavior });
      } else {
        controller().scrollToEnd({ behavior });
      }
    }
  }
>
  <if=content>
    <${content}/>
  </if>
  <else>
    <Icon name="ArrowDownIcon"/>
    <span class="sr-only">${direction === "end" ? "Scroll to end" : "Scroll to start"}</span>
  </else>
</Button>

// Port of shadcn's `message-scroller.tsx`'s `MessageScrollerContent`. Wraps
// `@shadcn/react/message-scroller`'s `MessageScroller.Content`, which owns a
// `MutationObserver` (childList) driving `handleContentChange`, plus a
// `ResizeObserver` on the same element driving `handleResize`, and renders a
// hidden tail spacer div as its last child (`data-message-scroller-spacer`).
//
// Ported using the same `<lifecycle>` idiom as viewport.marko for both
// observers; DOM/attrs/classes match the source exactly, including the
// spacer's `aria-hidden` + `hidden` + `data-message-scroller-spacer` markup.
import { cn } from "../../../lib/utils.ts";
import type { MessageScrollerControllerGetter } from "./lib/controller.ts";

export interface Input extends Marko.Input<"div"> {
  /** Controller getter provided by the nearest `<message-scroller-provider>`. */
  controller: MessageScrollerControllerGetter;
  /** Class name for the internal tail spacer used when anchoring turns near the top. */
  spacerClassName?: string;
}

<const/{ controller, class: className, content, spacerClassName, role, "aria-relevant": ariaRelevant, ...rest }=input/>

<div/el
  ...rest
  role=(role ?? "log")
  aria-relevant=(ariaRelevant ?? "additions")
  data-slot="message-scroller-content"
  class=cn("gap-8 flex h-max min-h-full flex-col", className)
>
  <${content}/>
  <div/spacerEl aria-hidden="true" data-message-scroller-spacer hidden class=spacerClassName/>
</div>

<lifecycle
  onMount() {
    const contentEl = el();
    controller().setContentElement(contentEl);
    controller().setSpacerElement(spacerEl());

    controller().handleContentChange();

    let mutationObserver: MutationObserver | undefined;
    if (typeof MutationObserver !== "undefined") {
      mutationObserver = new MutationObserver(() => {
        controller().handleContentChange();
      });
      mutationObserver.observe(contentEl, { childList: true });
    }

    let resizeFrame = 0;
    let resizeObserver: ResizeObserver | undefined;
    if (typeof ResizeObserver !== "undefined") {
      // Coalesce into rAF: handleResize mutates the spacer inside this
      // observed element, and resizing an observed element during delivery
      // fires "ResizeObserver loop completed with undelivered notifications"
      // (same rationale as the source).
      resizeObserver = new ResizeObserver(() => {
        window.cancelAnimationFrame(resizeFrame);
        resizeFrame = window.requestAnimationFrame(() => controller().handleResize());
      });
      resizeObserver.observe(contentEl);
    }

    // Marko merges onMount's RETURNED OBJECT into `this` (returning a bare
    // cleanup function is silently ignored) — onDestroy reads it back.
    return {
      cleanup: () => {
        mutationObserver?.disconnect();
        window.cancelAnimationFrame(resizeFrame);
        resizeObserver?.disconnect();
      },
    };
  }
  onDestroy() {
    this.cleanup?.();
    controller().setContentElement(null);
    controller().setSpacerElement(null);
  }
/>

// Port of shadcn's `message-scroller.tsx`'s `MessageScrollerItem`. Wraps
// `@shadcn/react/message-scroller`'s `MessageScroller.Item`, which registers
// (and unregisters) itself with the provider by `messageId` on mount/unmount
// via a ref callback.
import { cn } from "../../../lib/utils.ts";
import type { MessageScrollerControllerGetter } from "./lib/controller.ts";

export interface Input extends Marko.Input<"div"> {
  /** Controller getter provided by the nearest `<message-scroller-provider>`. */
  controller: MessageScrollerControllerGetter;
  /** Stable row id for scrollToMessage, visibility, and prepend preservation. */
  messageId?: string;
  /** Marks a turn boundary that newly appended anchors and last-anchor restore use. */
  scrollAnchor?: boolean;
}

<const/{ controller, messageId, scrollAnchor = false, class: className, content, ...rest }=input/>

<div/el
  ...rest
  data-message-id=messageId
  data-scroll-anchor=String(scrollAnchor)
  data-slot="message-scroller-item"
  class=cn("min-w-0 shrink-0 [contain-intrinsic-size:auto_10rem] [content-visibility:auto]", className)
>
  <${content}/>
</div>

<lifecycle
  onMount() {
    if (messageId) {
      controller().registerMessage(messageId, el());
    }
  }
  onDestroy() {
    if (messageId) {
      controller().registerMessage(messageId, null, el());
    }
  }
/>

// Port of shadcn's `message-scroller.tsx`'s `MessageScrollerProvider`, which
// itself just forwards to `@shadcn/react/message-scroller`'s
// `MessageScroller.Provider` — a HEADLESS component: it owns scroll state,
// anchoring, auto-follow, and visibility tracking, but renders no DOM element
// of its own (`MessageScrollerContext.Provider` in the source is a pure React
// context boundary).
//
// SIMPLIFICATION FROM SOURCE: Marko has no context primitive (per this
// project's stated gotchas: "React context -> pass values down as attrs from
// a container tag"). This port creates ONE `MessageScrollerController`
// instance (lib/controller.ts) per provider and passes it down explicitly as
// the `controller=` input to every descendant part (`message-scroller.marko`,
// `viewport.marko`, `content.marko`, `item.marko`, `button.marko`) instead of
// reading it from context. Because the controller is created here — not
// rendered as DOM — this file still renders NO wrapper element, matching the
// source's headless behavior exactly; only the mechanism for reaching
// descendants changed, not the DOM.
import {
  createMessageScrollerController,
  createMessageScrollerControllerHolder,
  type MessageScrollerControllerGetter,
} from "./lib/controller.ts";
import type { MessageScrollerDefaultScrollPosition } from "./lib/types.ts";

export interface Input {
  /** Follow new content at the bottom while the viewport is already at the end. */
  autoScroll?: boolean;
  /** Opening position on the first non-empty render, applied once. */
  defaultScrollPosition?: MessageScrollerDefaultScrollPosition;
  /** Distance from an edge that still counts as at-top/at-bottom. Defaults to 8. */
  scrollEdgeThreshold?: number;
  /** Extra top margin for a newly anchored row, added to scrollMargin. Defaults to 64. */
  scrollPreviousItemPeek?: number;
  /** Default margin on the aligned edge for commands and visibility. Defaults to 0. */
  scrollMargin?: number;
  /** Subtree that receives the controller GETTER as its single argument. */
  content?: Marko.Body<[MessageScrollerControllerGetter]>;
}

// SERIALIZATION RULE: the controller is a plain object full of functions and
// must never cross the server/client boundary. The template closure below is
// what descendants receive; it lazily builds the controller in the browser on
// first call (any part's mount or event may be first, so creation cannot be
// pinned to this provider's own onMount). During SSR only the holder —
// `{ current: null }` — is serialized.
<const/controllerHolder=createMessageScrollerControllerHolder()/>
<const/controller=() => (controllerHolder.current ??= createMessageScrollerController({
  autoScroll: input.autoScroll,
  defaultScrollPosition: input.defaultScrollPosition,
  scrollEdgeThreshold: input.scrollEdgeThreshold,
  scrollPreviousItemPeek: input.scrollPreviousItemPeek,
  scrollMargin: input.scrollMargin,
}))/>

<script>
  controller().setAutoScroll(input.autoScroll ?? false);
  if (input.defaultScrollPosition) {
    controller().setDefaultScrollPosition(input.defaultScrollPosition);
  }
</script>

<lifecycle
  onDestroy() {
    controllerHolder.current?.dispose();
    controllerHolder.current = null;
  }
/>

<${input.content}(controller)/>

// Port of shadcn's `message-scroller.tsx`'s `MessageScroller` (the styled
// frame). Wraps `@shadcn/react/message-scroller`'s `MessageScroller.Root`,
// which is a plain `<div ref={setRootElement} {...props} />` — this port
// registers the same element with the controller via `setRootElement` (a
// tag-variable ref, `el()`, standing in for the source's React `ref`
// callback) and otherwise renders byte-identical markup.
import { cn } from "../../../lib/utils.ts";
import type { MessageScrollerControllerGetter } from "./lib/controller.ts";

export interface Input extends Marko.Input<"div"> {
  /** Controller getter provided by the nearest `<message-scroller-provider>`. */
  controller: MessageScrollerControllerGetter;
}

<const/{ controller, class: className, content, ...rest }=input/>

<div/el
  ...rest
  data-slot="message-scroller"
  class=cn("group/message-scroller relative flex size-full min-h-0 flex-col overflow-hidden", className)
>
  <${content}/>
</div>

<lifecycle
  onMount() {
    controller().setRootElement(el());
  }
  onDestroy() {
    controller().setRootElement(null);
  }
/>

// Port of shadcn's `message-scroller.tsx`'s `MessageScrollerViewport`. Wraps
// `@shadcn/react/message-scroller`'s `MessageScroller.Viewport`, which owns
// native scroll/wheel/touch/keydown listeners plus a `ResizeObserver` on the
// viewport element itself.
//
// The source attaches these as React synthetic event props
// (onScroll/onWheel/onTouchMove/onKeyDown) and a `useEffect`-mounted
// ResizeObserver. This port uses the same native events as plain `on*`
// attributes (Marko compiles these to real DOM listeners, so behavior is
// identical) and moves the ResizeObserver into a `<lifecycle>` block — the
// task's requested "real scroll listener + ResizeObserver in an effect"
// idiom, using this project's actual effect primitive (`<lifecycle>`; Marko
// has no separate `<effect>` tag).
import { cn } from "../../../lib/utils.ts";
import type { MessageScrollerControllerGetter } from "./lib/controller.ts";
import { USER_SCROLL_KEYS } from "./lib/types.ts";

export interface Input extends Marko.Input<"div"> {
  /** Controller getter provided by the nearest `<message-scroller-provider>`. */
  controller: MessageScrollerControllerGetter;
  /** Keep the first visible messageId row stable on prepend. Defaults to true. */
  preserveScrollOnPrepend?: boolean;
}

<const/{
  controller,
  class: className,
  content,
  preserveScrollOnPrepend = true,
  role,
  tabindex,
  "aria-label": ariaLabel,
  ...rest
}=input/>

<script>
  controller().setPreserveScrollOnPrepend(preserveScrollOnPrepend);
</script>

<div/el
  ...rest
  role=(role ?? "region")
  aria-label=(ariaLabel ?? "Messages")
  tabindex=(tabindex ?? 0)
  data-slot="message-scroller-viewport"
  class=cn(
    "size-full min-h-0 min-w-0 scroll-fade-b scrollbar-thin scrollbar-gutter-stable overflow-y-auto overscroll-contain contain-content data-autoscrolling:scrollbar-thumb-transparent data-autoscrolling:scrollbar-track-transparent",
    className,
  )
  onWheel() {
    controller().userScrollIntent();
  }
  onTouchMove() {
    controller().userScrollIntent();
  }
  onKeyDown(event: KeyboardEvent) {
    if (USER_SCROLL_KEYS.has(event.key)) {
      controller().userScrollIntent();
    }
  }
>
  <${content}/>
</div>

<lifecycle
  onMount() {
    const viewport = el();
    controller().setViewportElement(viewport);

    // `scroll` does not bubble and never reaches Marko's document-level
    // delegated listeners, so an `onScroll` attribute here would be dead —
    // it must be attached directly to the element.
    const onScroll = () => controller().syncAfterScroll();
    viewport.addEventListener("scroll", onScroll, { passive: true });

    if (typeof ResizeObserver === "undefined") {
      return {
        cleanup: () => viewport.removeEventListener("scroll", onScroll),
      };
    }

    // Coalesce into rAF: handleResize mutates the spacer inside the observed
    // content, and resizing an observed element during delivery fires
    // "ResizeObserver loop completed with undelivered notifications" (same
    // rationale as the source).
    let frame = 0;
    const observer = new ResizeObserver(() => {
      window.cancelAnimationFrame(frame);
      frame = window.requestAnimationFrame(() => controller().handleResize());
    });
    observer.observe(viewport);

    // Marko merges onMount's RETURNED OBJECT into `this` (returning a bare
    // cleanup function is silently ignored) — onDestroy reads it back.
    return {
      cleanup: () => {
        viewport.removeEventListener("scroll", onScroll);
        window.cancelAnimationFrame(frame);
        observer.disconnect();
      },
    };
  }
  onDestroy() {
    this.cleanup?.();
    controller().setViewportElement(null);
  }
/>

// Framework-agnostic port of the shadcn `@shadcn/react/message-scroller`
// package's `use-message-scroller-refs.ts` + `use-message-scroller-commands.ts`
// + `use-message-scroller-controller.ts` + `stores.ts`, collapsed into one
// factory function.
//
// SIMPLIFICATION FROM SOURCE: the React source splits this logic across three
// hooks (refs / commands / controller) plus a `useSyncExternalStore`-shaped
// store module, because React needs stable callback identities across
// re-renders and a store-subscription bridge for `useSyncExternalStore`.
// Marko has no re-render cycle to be stable across and no
// `useSyncExternalStore` — it has `<let>` reactive locals wired at the
// component boundary instead — so this port collapses everything into one
// plain closure-based controller object built once per `<MessageScrollerProvider>`
// instance. The two external stores are kept (as plain listener-set pub/sub)
// because two different Marko components (`Button`, and any external
// consumer of `useMessageScrollerScrollable`/`useMessageScrollerVisibility`)
// need to react to state this controller owns without a shared parent
// re-render to piggyback on — see message-scroller-provider.marko's header
// comment for how `<let>` is wired to these subscriptions.
//
// Every piece of *behavior* (mode transitions, anchoring, prepend
// preservation, tail-spacer math) is a verbatim port of the source's logic;
// only the plumbing that carried it across React's render model changed.
import {
  getContentBottom,
  getElementScrollTop,
  getElementTop,
  getElementViewportTop,
  getFirstVisibleMessageItem,
  getFlexGap,
  getLastScrollAnchor,
  getMaxScrollTop,
  getMessageScrollerItems,
  getMessageScrollerScrollable,
  getMessageScrollerVisibilityState,
  getNewScrollAnchor,
  getTailSpacerHeight,
  getUnanchoredScrollAnchor,
  hasMultipleNewScrollAnchors,
} from "./geometry.ts";
import {
  AUTOSCROLLING_CLEAR_DELAY,
  DEFAULT_SCROLL_EDGE_THRESHOLD,
  DEFAULT_SCROLL_MARGIN,
  DEFAULT_SCROLL_PREVIOUS_ITEM_PEEK,
  EMPTY_MESSAGE_SCROLLER_VISIBILITY_STATE,
  SCROLL_POSITION_EPSILON,
} from "./types.ts";
import type {
  MessageScrollerDefaultScrollPosition,
  MessageScrollerMode,
  MessageScrollerScrollable,
  MessageScrollerScrollOptions,
  MessageScrollerVisibilityState,
} from "./types.ts";

export type MessageScrollerProviderOptions = {
  autoScroll?: boolean;
  defaultScrollPosition?: MessageScrollerDefaultScrollPosition;
  scrollEdgeThreshold?: number;
  scrollPreviousItemPeek?: number;
  scrollMargin?: number;
};

// Minimal pub/sub, standing in for the source's useSyncExternalStore-shaped
// store (see this file's header comment).
function createStore<T>(initialSnapshot: T, isEqual: (a: T, b: T) => boolean) {
  let snapshot = initialSnapshot;
  const listeners = new Set<() => void>();

  return {
    getSnapshot: () => snapshot,
    hasListeners: () => listeners.size > 0,
    setSnapshot: (next: T) => {
      if (isEqual(snapshot, next)) return;
      snapshot = next;
      listeners.forEach((listener) => listener());
    },
    subscribe: (listener: () => void, onFirstSubscribe?: () => void, onLastUnsubscribe?: () => void) => {
      const wasEmpty = listeners.size === 0;
      listeners.add(listener);
      if (wasEmpty) onFirstSubscribe?.();
      return () => {
        listeners.delete(listener);
        if (listeners.size === 0) onLastUnsubscribe?.();
      };
    },
  };
}

function areScrollStatesEqual(current: MessageScrollerScrollable, next: MessageScrollerScrollable) {
  return current.start === next.start && current.end === next.end;
}

function areVisibilityStatesEqual(current: MessageScrollerVisibilityState, next: MessageScrollerVisibilityState) {
  if (current.currentAnchorId !== next.currentAnchorId) return false;
  if (current.visibleMessageIds.length !== next.visibleMessageIds.length) return false;
  return current.visibleMessageIds.every((messageId, index) => messageId === next.visibleMessageIds[index]);
}

export function createMessageScrollerController(options: MessageScrollerProviderOptions = {}) {
  let autoScroll = options.autoScroll ?? false;
  const scrollEdgeThreshold = options.scrollEdgeThreshold ?? DEFAULT_SCROLL_EDGE_THRESHOLD;
  const scrollPreviousItemPeek = options.scrollPreviousItemPeek ?? DEFAULT_SCROLL_PREVIOUS_ITEM_PEEK;
  const scrollMargin = options.scrollMargin ?? DEFAULT_SCROLL_MARGIN;
  let defaultScrollPosition = options.defaultScrollPosition ?? "end";

  // --- ref bag (plain mutable closure state) ---
  let autoscrolling = false;
  // number, not ReturnType<typeof setTimeout>: this runs in the browser and
  // uses window.setTimeout, which returns a numeric handle.
  let autoscrollingTimeout: number | null = null;
  let streamingTurn: HTMLElement | null = null;
  let content: HTMLElement | null = null;
  let defaultScrollPositionApplied = false;
  let firstItem: HTMLElement | null = null;
  let itemCount = 0;
  let lastScrollTop = 0;
  const messageElements = new Map<string, HTMLElement>();
  let mode: MessageScrollerMode = autoScroll ? "following-bottom" : "free-scrolling";
  let pendingScrollFrame: number | null = null;
  let pendingScrollToMessage: { messageId: string; options?: MessageScrollerScrollOptions } | null = null;
  let prependRestore: { element: HTMLElement; viewportTop: number } | null = null;
  let preserveScrollOnPrepend = true;
  let root: HTMLElement | null = null;
  let spacerGap = 0;
  let spacerHeight = 0;
  let spacer: HTMLElement | null = null;
  let stateFrame: number | null = null;
  let viewport: HTMLElement | null = null;
  let visibilityFrame: number | null = null;
  let visibilityObserver: IntersectionObserver | null = null;
  let visibleMessageIds = new Set<string>();
  const handledScrollAnchors = new WeakSet<HTMLElement>();

  const stateStore = createStore<MessageScrollerScrollable>({ start: false, end: false }, areScrollStatesEqual);
  const visibilityStore = createStore<MessageScrollerVisibilityState>(EMPTY_MESSAGE_SCROLLER_VISIBILITY_STATE, areVisibilityStatesEqual);

  function writeStateAttributes(state: MessageScrollerScrollable) {
    const scrollable = [state.start && "start", state.end && "end"].filter(Boolean).join(" ");

    for (const element of [root, viewport]) {
      if (!element) continue;

      if (scrollable) {
        element.setAttribute("data-scrollable", scrollable);
      } else {
        element.removeAttribute("data-scrollable");
      }

      element.toggleAttribute("data-autoscrolling", autoscrolling);
    }
  }

  // Owns the one follow-bottom transition: arm at the bottom, release on any
  // scroll away (including a scrollbar drag), suppressed during a
  // programmatic scroll so the auto-scroll animation cannot release itself.
  function reconcileFollowMode(scrollable: MessageScrollerScrollable) {
    const scrollTop = viewport?.scrollTop ?? 0;
    const scrolledUp = scrollTop < lastScrollTop - SCROLL_POSITION_EPSILON;

    lastScrollTop = scrollTop;

    if (autoScroll && !scrollable.end && mode !== "settling-jump" && mode !== "anchored-to-message") {
      mode = "following-bottom";
    } else if (mode === "following-bottom" && scrollable.end && scrolledUp && !autoscrolling) {
      mode = "free-scrolling";
    }
  }

  function commitScrollState() {
    const nextState = getMessageScrollerScrollable({ content, scrollEdgeThreshold, spacer, viewport });

    reconcileFollowMode(nextState);

    const publishedState = mode === "following-bottom" ? { ...nextState, end: false } : nextState;

    writeStateAttributes(publishedState);
    stateStore.setSnapshot(publishedState);
  }

  function scheduleStateCommit() {
    if (stateFrame !== null) return;
    stateFrame = window.requestAnimationFrame(() => {
      stateFrame = null;
      commitScrollState();
    });
  }

  function scheduleVisibilitySync() {
    if (!visibilityStore.hasListeners()) return;
    if (visibilityFrame !== null) return;

    visibilityFrame = window.requestAnimationFrame(() => {
      visibilityFrame = null;
      if (!visibilityStore.hasListeners()) return;

      visibilityStore.setSnapshot(
        getMessageScrollerVisibilityState({
          content,
          scrollMargin,
          scrollPreviousItemPeek,
          spacer,
          viewport,
          visibleMessageIds,
        }),
      );
    });
  }

  // --- commands ---
  function setAutoScrolling(next: boolean) {
    if (autoscrollingTimeout !== null) {
      window.clearTimeout(autoscrollingTimeout);
      autoscrollingTimeout = null;
    }

    if (autoscrolling !== next) {
      autoscrolling = next;
      commitScrollState();
    }

    if (next) {
      autoscrollingTimeout = window.setTimeout(() => {
        autoscrollingTimeout = null;
        autoscrolling = false;
        commitScrollState();
      }, AUTOSCROLLING_CLEAR_DELAY);
    }
  }

  function setTailSpacerHeight(height: number) {
    if (!spacer) return;

    const nextHeight = Math.max(0, Math.ceil(height));

    if (spacerHeight === nextHeight) return;

    spacerHeight = nextHeight;
    spacer.hidden = nextHeight === 0;
    spacer.style.height = `${nextHeight}px`;
    spacer.style.marginTop = nextHeight > 0 ? `${-spacerGap}px` : "";
  }

  function scrollToPosition(scrollTop: number, { behavior = "auto", autoscrollingFlag = false }: { behavior?: ScrollBehavior; autoscrollingFlag?: boolean } = {}) {
    if (!viewport) return;

    const nextScrollTop = Math.max(0, scrollTop);

    if (Math.abs(viewport.scrollTop - nextScrollTop) <= SCROLL_POSITION_EPSILON) {
      viewport.scrollTop = nextScrollTop;
      commitScrollState();
      return;
    }

    if (autoscrollingFlag) {
      setAutoScrolling(true);
    }

    viewport.scrollTo({ top: nextScrollTop, behavior });
    scheduleStateCommit();
  }

  function scrollToStart({ behavior = "auto" }: MessageScrollerScrollOptions = {}) {
    if (!viewport) return false;

    setTailSpacerHeight(0);
    streamingTurn = null;
    mode = "free-scrolling";
    scrollToPosition(0, { behavior });
    scheduleVisibilitySync();

    return true;
  }

  function scrollToEnd({ behavior = "auto" }: MessageScrollerScrollOptions = {}) {
    if (!viewport) return false;

    setTailSpacerHeight(0);
    streamingTurn = null;
    mode = autoScroll ? "following-bottom" : "free-scrolling";
    scrollToPosition(getMaxScrollTop(viewport), { autoscrollingFlag: true, behavior });
    scheduleVisibilitySync();

    return true;
  }

  function scrollToElement(
    element: HTMLElement,
    { align = "start", behavior = "auto", scrollMargin: marginOverride = scrollMargin }: MessageScrollerScrollOptions = {},
    { keepPreviousPeek = false }: { keepPreviousPeek?: boolean } = {},
  ) {
    if (!content || !viewport || !content.contains(element)) return false;

    const scrollTop = getElementScrollTop({
      align,
      element,
      scrollMargin: keepPreviousPeek ? marginOverride + scrollPreviousItemPeek : marginOverride,
      spacer,
      viewport,
    });

    const nextSpacerHeight = getTailSpacerHeight({ content, scrollTop, spacer, viewport });

    setTailSpacerHeight(nextSpacerHeight);
    prependRestore = { element, viewportTop: getElementViewportTop(element, viewport) };

    mode = keepPreviousPeek ? "anchored-to-message" : "settling-jump";
    streamingTurn = keepPreviousPeek ? element : null;

    scrollToPosition(scrollTop, { behavior });
    scheduleVisibilitySync();

    return true;
  }

  function reanchorToAnchoredMessage() {
    const element = streamingTurn;

    if (!element || !element.isConnected || mode !== "anchored-to-message") {
      return false;
    }

    return scrollToElement(element, { align: "start" }, { keepPreviousPeek: true });
  }

  function scrollToMessage(messageId: string, scrollOptions?: MessageScrollerScrollOptions) {
    const element = messageElements.get(messageId);

    if (!element) {
      if (itemCount === 0) {
        pendingScrollToMessage = { messageId, options: scrollOptions };
        defaultScrollPositionApplied = true;
        return true;
      }
      return false;
    }

    defaultScrollPositionApplied = true;

    if (scrollToElement(element, scrollOptions)) {
      pendingScrollToMessage = null;
      return true;
    }

    pendingScrollToMessage = { messageId, options: scrollOptions };
    return true;
  }

  function flushPendingScrollToMessage() {
    const pending = pendingScrollToMessage;
    if (!pending) return false;

    const element = messageElements.get(pending.messageId);
    if (!element) return false;

    const handled = scrollToElement(element, pending.options);
    if (!handled) return false;

    pendingScrollToMessage = null;
    defaultScrollPositionApplied = true;
    return true;
  }

  // --- prepend anchoring ---
  function restorePrependedAnchor() {
    const anchor = prependRestore;

    if (!anchor || !viewport || !anchor.element.isConnected) {
      return false;
    }

    const nextViewportTop = getElementViewportTop(anchor.element, viewport);
    const delta = nextViewportTop - anchor.viewportTop;

    if (Math.abs(delta) <= SCROLL_POSITION_EPSILON) {
      return false;
    }

    viewport.scrollTop += delta;
    anchor.viewportTop = getElementViewportTop(anchor.element, viewport);
    scheduleStateCommit();
    scheduleVisibilitySync();

    return true;
  }

  function capturePrependAnchor() {
    if (!content || !viewport) {
      prependRestore = null;
      return;
    }

    const anchor = getFirstVisibleMessageItem({ content, spacer, viewport });

    prependRestore = anchor ? { element: anchor, viewportTop: getElementViewportTop(anchor, viewport) } : null;
  }

  function schedulePendingScrollToMessageFlush() {
    if (pendingScrollFrame !== null) return;

    pendingScrollFrame = window.requestAnimationFrame(() => {
      pendingScrollFrame = null;
      if (flushPendingScrollToMessage()) {
        capturePrependAnchor();
      }
    });
  }

  function applyDefaultScrollPosition() {
    if (!defaultScrollPosition || defaultScrollPositionApplied || itemCount === 0) {
      return false;
    }

    let handled = false;

    if (defaultScrollPosition === "last-anchor") {
      const anchor = content && viewport ? getLastScrollAnchor(getMessageScrollerItems(content, spacer)) : null;

      if (!content || !viewport || !anchor) {
        handled = scrollToEnd({ behavior: "auto" });
      } else {
        const anchorTop = getElementTop(anchor, viewport);
        const contentBottom = getContentBottom({ content, spacer, viewport });
        const lastTurnFits = contentBottom - anchorTop <= viewport.clientHeight;

        handled = lastTurnFits ? scrollToEnd({ behavior: "auto" }) : scrollToElement(anchor, { align: "start" }, { keepPreviousPeek: true });
      }
    } else {
      handled = defaultScrollPosition === "end" ? scrollToEnd({ behavior: "auto" }) : scrollToStart({ behavior: "auto" });
    }

    if (!handled) return false;

    defaultScrollPositionApplied = true;
    return true;
  }

  function handleContentChange() {
    if (!content) return;

    const items = getMessageScrollerItems(content, spacer);
    const previousItemCount = itemCount;
    const previousFirstItem = firstItem;

    itemCount = items.length;
    firstItem = items[0] ?? null;

    function reconcileScrollPosition() {
      if (flushPendingScrollToMessage()) return;

      if (previousItemCount === 0) {
        if (applyDefaultScrollPosition()) return;

        if (items.length > 0 && autoScroll && scrollToEnd({ behavior: "auto" })) return;

        commitScrollState();
        scheduleVisibilitySync();
        return;
      }

      const previousFirstItemIndex = previousFirstItem ? items.indexOf(previousFirstItem) : -1;
      const didPrepend = preserveScrollOnPrepend && previousFirstItemIndex > 0;

      if (didPrepend) {
        restorePrependedAnchor();
        return;
      }

      if (items.length > previousItemCount) {
        const anchor = getNewScrollAnchor(items, previousItemCount);

        if (anchor) {
          if (autoScroll && mode === "following-bottom" && hasMultipleNewScrollAnchors(items, previousItemCount)) {
            scrollToEnd({ behavior: "auto" });
            return;
          }

          scrollToElement(anchor, { align: "start" }, { keepPreviousPeek: true });
          handledScrollAnchors.add(anchor);
          return;
        }
      }

      if (items.length === previousItemCount) {
        const anchor = getUnanchoredScrollAnchor(items, handledScrollAnchors);

        if (anchor) {
          scrollToElement(anchor, { align: "start" }, { keepPreviousPeek: true });
          handledScrollAnchors.add(anchor);
          return;
        }
      }

      if (mode === "following-bottom" && autoScroll) {
        scrollToEnd({ behavior: "auto" });
      } else {
        commitScrollState();
        scheduleVisibilitySync();
      }
    }

    reconcileScrollPosition();
    capturePrependAnchor();
  }

  function handleResize() {
    if (mode === "following-bottom" && autoScroll) {
      scrollToEnd({ behavior: "auto" });
      return;
    }

    const previousSpacerHeight = spacerHeight;

    if (reanchorToAnchoredMessage()) {
      if (autoScroll && previousSpacerHeight > 0 && spacerHeight === 0) {
        scrollToEnd({ behavior: "auto" });
      }
      return;
    }

    scheduleStateCommit();
    scheduleVisibilitySync();
  }

  function observeVisibility() {
    if (!viewport || !visibilityStore.hasListeners()) return;

    if (typeof IntersectionObserver === "undefined") {
      scheduleVisibilitySync();
      return;
    }

    if (!visibilityObserver) {
      visibilityObserver = new IntersectionObserver(
        (entries) => {
          for (const entry of entries) {
            const messageId = (entry.target as HTMLElement).dataset.messageId;
            if (!messageId) continue;

            if (entry.isIntersecting) {
              visibleMessageIds.add(messageId);
            } else {
              visibleMessageIds.delete(messageId);
            }
          }

          scheduleVisibilitySync();
        },
        {
          root: viewport,
          rootMargin: `${-(scrollMargin + scrollPreviousItemPeek)}px 0px 0px 0px`,
          threshold: [0, 0.01, 0.5, 1],
        },
      );
    }

    messageElements.forEach((element) => {
      visibilityObserver?.observe(element);
    });
    scheduleVisibilitySync();
  }

  function unobserveVisibility() {
    if (visibilityFrame !== null) {
      window.cancelAnimationFrame(visibilityFrame);
      visibilityFrame = null;
    }

    visibilityObserver?.disconnect();
    visibilityObserver = null;
    visibleMessageIds.clear();
    visibilityStore.setSnapshot(EMPTY_MESSAGE_SCROLLER_VISIBILITY_STATE);
  }

  function registerMessage(messageId: string, element: HTMLElement | null, removedElement?: HTMLElement | null) {
    if (element) {
      messageElements.set(messageId, element);
      visibilityObserver?.observe(element);
      scheduleVisibilitySync();

      if (pendingScrollToMessage?.messageId === messageId) {
        schedulePendingScrollToMessageFlush();
      }
      return;
    }

    if (removedElement && messageElements.get(messageId) === removedElement) {
      messageElements.delete(messageId);
      visibleMessageIds.delete(messageId);
      visibilityObserver?.unobserve(removedElement);
      scheduleVisibilitySync();
    }
  }

  function userScrollIntent() {
    if (mode === "following-bottom" || mode === "anchored-to-message" || mode === "settling-jump") {
      streamingTurn = null;
      mode = "free-scrolling";
    }
  }

  function mirrorStateAttributes() {
    writeStateAttributes(stateStore.getSnapshot());
  }

  function setRootElement(element: HTMLElement | null) {
    root = element;
    if (element) mirrorStateAttributes();
  }

  function setViewportElement(element: HTMLElement | null) {
    viewport = element;
    if (element) mirrorStateAttributes();
  }

  function setContentElement(element: HTMLElement | null) {
    content = element;
  }

  function setSpacerElement(element: HTMLElement | null) {
    spacer = element;
    spacerGap = getFlexGap(element?.parentElement ?? null);
  }

  function setPreserveScrollOnPrepend(next: boolean) {
    preserveScrollOnPrepend = next;
  }

  function syncAfterScroll() {
    commitScrollState();
    scheduleVisibilitySync();
    capturePrependAnchor();
  }

  function setAutoScroll(next: boolean) {
    autoScroll = next;
  }

  function setDefaultScrollPosition(next: MessageScrollerDefaultScrollPosition) {
    if (defaultScrollPosition !== next) {
      defaultScrollPosition = next;
      defaultScrollPositionApplied = false;
    }
  }

  // Mirrors the source's `useLayoutEffect(() => applyDefaultScrollPosition(), [...])`
  // + the mount-time autoScroll layout effect. Call once the root/viewport/
  // content elements have all attached (see message-scroller-provider.marko).
  function init() {
    applyDefaultScrollPosition();

    if (autoScroll && mode === "following-bottom" && itemCount > 0) {
      scrollToEnd({ behavior: "auto" });
      return;
    }

    commitScrollState();
  }

  // Mirrors the source's controller-level cleanup effect (StrictMode-safe
  // frame/timeout teardown). Call from the provider's `<lifecycle>` cleanup.
  function dispose() {
    if (stateFrame !== null) {
      window.cancelAnimationFrame(stateFrame);
      stateFrame = null;
    }
    if (visibilityFrame !== null) {
      window.cancelAnimationFrame(visibilityFrame);
      visibilityFrame = null;
    }
    if (autoscrollingTimeout !== null) {
      window.clearTimeout(autoscrollingTimeout);
      autoscrollingTimeout = null;
    }
    if (pendingScrollFrame !== null) {
      window.cancelAnimationFrame(pendingScrollFrame);
      pendingScrollFrame = null;
    }
    visibilityObserver?.disconnect();
    visibilityObserver = null;
  }

  return {
    // element registration
    setRootElement,
    setViewportElement,
    setContentElement,
    setSpacerElement,
    setPreserveScrollOnPrepend,
    registerMessage,
    // lifecycle
    init,
    dispose,
    // event entry points (wired to native listeners by the parts)
    handleContentChange,
    handleResize,
    syncAfterScroll,
    userScrollIntent,
    observeVisibility,
    unobserveVisibility,
    // commands
    scrollToStart,
    scrollToEnd,
    scrollToMessage,
    // config setters (mirror React prop changes)
    setAutoScroll,
    setDefaultScrollPosition,
    // stores
    stateStore,
    visibilityStore,
  };
}

export type MessageScrollerController = ReturnType<typeof createMessageScrollerController>;

/** Getter contract passed from `<message-scroller-provider>` to every part —
 * a template closure, so tag input stays serializable (the controller itself
 * is a plain object full of functions and must never cross a tag boundary). */
export type MessageScrollerControllerGetter = () => MessageScrollerController;

/** Per-provider holder the lazy getter closes over; serializes as `{ current: null }`
 * during SSR because the controller is only created in the browser. */
export function createMessageScrollerControllerHolder(): {
  current: MessageScrollerController | null;
} {
  return { current: null };
}

// Faithful port of the shadcn `@shadcn/react/message-scroller` package's
// `geometry.ts`. Pure DOM math, framework-agnostic already in the source, so
// this file is copied over verbatim (only the import path for shared types
// changed, and `MessageScrollerScrollAlign` inlined from `./types`).
import type { MessageScrollerScrollAlign, MessageScrollerScrollable } from "./types.ts";
import { EMPTY_MESSAGE_SCROLLER_SCROLLABLE, EMPTY_MESSAGE_SCROLLER_VISIBILITY_STATE, SCROLL_POSITION_EPSILON } from "./types.ts";
import type { MessageScrollerVisibilityState } from "./types.ts";

export function getMessageScrollerScrollable({
  content,
  scrollEdgeThreshold,
  spacer,
  viewport,
}: {
  content: HTMLElement | null;
  scrollEdgeThreshold: number;
  spacer: HTMLElement | null;
  viewport: HTMLElement | null;
}): MessageScrollerScrollable {
  if (!viewport || !content) {
    return EMPTY_MESSAGE_SCROLLER_SCROLLABLE;
  }

  const contentBottom = getContentBottom({ content, spacer, viewport });

  return {
    start: viewport.scrollTop > scrollEdgeThreshold,
    end: contentBottom - viewport.scrollTop - viewport.clientHeight > scrollEdgeThreshold,
  };
}

export function getMessageScrollerVisibilityState({
  content,
  scrollMargin,
  scrollPreviousItemPeek,
  spacer,
  viewport,
  visibleMessageIds,
}: {
  content: HTMLElement | null;
  scrollMargin: number;
  scrollPreviousItemPeek: number;
  spacer: HTMLElement | null;
  viewport: HTMLElement | null;
  visibleMessageIds: Set<string>;
}): MessageScrollerVisibilityState {
  if (!content || !viewport) {
    return EMPTY_MESSAGE_SCROLLER_VISIBILITY_STATE;
  }

  const viewportRect = viewport.getBoundingClientRect();
  // The reading line sits scrollPreviousItemPeek below scrollMargin: anchored
  // turns land there with the previous turn peeking above. A row only peeking
  // in that band has not been read down to yet, so it counts as neither
  // visible nor current.
  const lineTop = viewportRect.top + scrollMargin + scrollPreviousItemPeek;
  const trackByLayout = typeof IntersectionObserver === "undefined";

  const visible: string[] = [];
  let currentAnchorId: string | null = null;

  // Walk rows in document order so visible ids come out top-to-bottom.
  for (const item of getMessageScrollerItems(content, spacer)) {
    const messageId = item.dataset.messageId;

    if (!messageId) {
      continue;
    }

    const isAnchor = item.dataset.scrollAnchor === "true";
    // Anchors need a rect to place the current line; non-anchors lean on the
    // observer set (or a rect in the no-observer fallback).
    const rect = isAnchor || trackByLayout ? item.getBoundingClientRect() : null;

    const isVisible = trackByLayout && rect ? rect.bottom > lineTop && rect.top < viewportRect.bottom : visibleMessageIds.has(messageId);

    if (isVisible) {
      visible.push(messageId);
    }

    // Current is the last anchor to have reached the reading line: the turn
    // you scrolled to (placed at the line) wins over newer turns lower down,
    // the previous turn peeking above the line has been passed, and it stays
    // current even after its header scrolls above the viewport.
    if (isAnchor && rect && rect.top <= lineTop + SCROLL_POSITION_EPSILON) {
      currentAnchorId = messageId;
    }
  }

  if (visible.length === 0 && currentAnchorId === null) {
    return EMPTY_MESSAGE_SCROLLER_VISIBILITY_STATE;
  }

  return {
    currentAnchorId,
    visibleMessageIds: visible,
  };
}

export function getMessageScrollerItems(content: HTMLElement, spacer: HTMLElement | null) {
  return Array.from(content.children).filter((child): child is HTMLElement => child instanceof HTMLElement && child !== spacer);
}

export function getNewScrollAnchor(items: HTMLElement[], previousItemCount: number) {
  for (let index = previousItemCount; index < items.length; index++) {
    const item = items[index];

    if (item?.dataset.scrollAnchor === "true") {
      return item;
    }
  }

  return null;
}

export function getUnanchoredScrollAnchor(items: HTMLElement[], handledAnchors: { has(element: HTMLElement): boolean }) {
  for (const item of items) {
    if (item.dataset.scrollAnchor === "true" && !handledAnchors.has(item)) {
      return item;
    }
  }

  return null;
}

export function hasMultipleNewScrollAnchors(items: HTMLElement[], previousItemCount: number) {
  let count = 0;

  for (let index = previousItemCount; index < items.length; index++) {
    const item = items[index];

    if (item?.dataset.scrollAnchor !== "true") {
      continue;
    }

    count += 1;

    if (count > 1) {
      return true;
    }
  }

  return false;
}

export function getLastScrollAnchor(items: HTMLElement[]) {
  for (let index = items.length - 1; index >= 0; index--) {
    const item = items[index];

    if (item?.dataset.scrollAnchor === "true") {
      return item;
    }
  }

  return null;
}

export function getFirstVisibleMessageItem({ content, spacer, viewport }: { content: HTMLElement; spacer: HTMLElement | null; viewport: HTMLElement }) {
  const viewportRect = viewport.getBoundingClientRect();

  for (const item of getMessageScrollerItems(content, spacer)) {
    if (!item.dataset.messageId) {
      continue;
    }

    const rect = item.getBoundingClientRect();

    if (rect.bottom > viewportRect.top && rect.top < viewportRect.bottom) {
      return item;
    }
  }

  return null;
}

export function getElementScrollTop({
  align,
  element,
  scrollMargin,
  spacer,
  viewport,
}: {
  align: MessageScrollerScrollAlign;
  element: HTMLElement;
  scrollMargin: number;
  spacer: HTMLElement | null;
  viewport: HTMLElement;
}) {
  const elementTop = getElementTop(element, viewport);
  const elementHeight = element.getBoundingClientRect().height;
  const contentPadding = getContentBlockPadding(spacer);

  if (align === "center") {
    const insetHeight = Math.max(0, viewport.clientHeight - contentPadding.start - contentPadding.end);

    return elementTop - contentPadding.start - (insetHeight - elementHeight) / 2 - scrollMargin;
  }

  if (align === "end") {
    return elementTop - viewport.clientHeight + elementHeight + contentPadding.end + scrollMargin;
  }

  if (align === "nearest") {
    const elementBottom = elementTop + elementHeight;
    const viewportTop = viewport.scrollTop + contentPadding.start;
    const viewportBottom = viewport.scrollTop + viewport.clientHeight - contentPadding.end;

    if (elementTop >= viewportTop && elementBottom <= viewportBottom) {
      return viewport.scrollTop;
    }

    if (elementTop < viewportTop) {
      return elementTop - contentPadding.start - scrollMargin;
    }

    return elementBottom - viewport.clientHeight + contentPadding.end + scrollMargin;
  }

  return elementTop - contentPadding.start - scrollMargin;
}

export function getElementTop(element: HTMLElement, viewport: HTMLElement) {
  const elementRect = element.getBoundingClientRect();
  const viewportRect = viewport.getBoundingClientRect();

  return elementRect.top - viewportRect.top + viewport.scrollTop;
}

export function getElementViewportTop(element: HTMLElement, viewport: HTMLElement) {
  return element.getBoundingClientRect().top - viewport.getBoundingClientRect().top;
}

export function getTailSpacerHeight({ content, scrollTop, spacer, viewport }: { content: HTMLElement; scrollTop: number; spacer: HTMLElement | null; viewport: HTMLElement }) {
  const contentBottom = getContentBottom({ content, spacer, viewport });

  return scrollTop + viewport.clientHeight - contentBottom;
}

export function getContentBottom({ content, spacer, viewport }: { content: HTMLElement; spacer: HTMLElement | null; viewport: HTMLElement }) {
  const items = getMessageScrollerItems(content, spacer);
  const padding = getBlockPadding(content);
  const viewportRect = viewport.getBoundingClientRect();
  const scrollTop = viewport.scrollTop;
  let contentBottom = padding.start + padding.end;

  for (const item of items) {
    const rect = item.getBoundingClientRect();

    contentBottom = Math.max(contentBottom, rect.bottom - viewportRect.top + scrollTop + padding.end);
  }

  return contentBottom;
}

export function getMaxScrollTop(viewport: HTMLElement) {
  return Math.max(0, viewport.scrollHeight - viewport.clientHeight);
}

function getBlockPadding(element: HTMLElement) {
  const style = window.getComputedStyle(element);

  return {
    end: readCssPixel(style.paddingBlockEnd || style.paddingBottom),
    start: readCssPixel(style.paddingBlockStart || style.paddingTop),
  };
}

function getContentBlockPadding(spacer: HTMLElement | null) {
  const content = spacer?.parentElement;

  if (!content) {
    return {
      end: 0,
      start: 0,
    };
  }

  return getBlockPadding(content);
}

export function getFlexGap(element: HTMLElement | null) {
  if (!element) {
    return 0;
  }

  const style = window.getComputedStyle(element);
  const gap = style.rowGap === "normal" ? style.gap : style.rowGap;

  return readCssPixel(gap);
}

function readCssPixel(value: string | undefined) {
  if (!value) {
    return 0;
  }

  const number = Number.parseFloat(value);

  return Number.isFinite(number) ? number : 0;
}

// Port of the shadcn `@shadcn/react/message-scroller` package's `types.ts`,
// trimmed to the framework-agnostic subset the Marko controller needs
// (React-specific context/store/ref types are dropped — Marko has no
// context primitive, see controller.ts's header comment for how state
// threading is redone).

// Default scrollEdgeThreshold. Sub-pixel tolerance so edge detection does not
// flicker across engines that round scrollTop differently.
export const DEFAULT_SCROLL_EDGE_THRESHOLD = 8;

// Default scrollPreviousItemPeek. Pixels of the previous item kept visible
// above a newly anchored row.
export const DEFAULT_SCROLL_PREVIOUS_ITEM_PEEK = 64;

// Default scrollMargin for scrollToMessage and programmatic targets.
export const DEFAULT_SCROLL_MARGIN = 0;

// Two fractional scrollTop values within this range are treated as equal, to
// absorb zoom and HiDPI rounding drift.
export const SCROLL_POSITION_EPSILON = 0.5;

// How long (ms) data-autoscrolling stays set during a programmatic smooth
// scroll before clearing.
export const AUTOSCROLLING_CLEAR_DELAY = 180;

// Viewport keys that count as deliberate scroll intent and release
// follow-bottom.
export const USER_SCROLL_KEYS = new Set(["ArrowDown", "ArrowUp", "End", "Home", "PageDown", "PageUp", " "]);

// Internal scroll mode. Derived from intent and commands; decides how the
// viewport reacts to content and resize.
export type MessageScrollerMode =
  | "following-bottom" // autoScroll on, pinned to the latest message.
  | "free-scrolling" // reader scrolled away; position left alone (prepends still preserved).
  | "anchored-to-message" // holding a turn at the reading line while it streams.
  | "settling-jump"; // a programmatic jump is animating; intent detection suppressed until it settles.

// Where a saved transcript opens on the first non-empty render.
export type MessageScrollerDefaultScrollPosition = "start" | "end" | "last-anchor";

// Which transcript edge MessageScrollerButton scrolls toward.
export type MessageScrollerButtonDirection = "start" | "end";

// Viewport alignment for scrollToMessage and programmatic jumps.
export type MessageScrollerScrollAlign = "start" | "center" | "end" | "nearest";

// Options for scrollToMessage, scrollToEnd, and scrollToStart.
export type MessageScrollerScrollOptions = {
  align?: MessageScrollerScrollAlign;
  behavior?: ScrollBehavior;
  scrollMargin?: number;
};

// Scroll snapshot: which edges the viewport can still scroll toward.
export type MessageScrollerScrollable = {
  start: boolean;
  end: boolean;
};

// Visibility snapshot.
export type MessageScrollerVisibilityState = {
  currentAnchorId: string | null;
  visibleMessageIds: string[];
};

export const EMPTY_MESSAGE_SCROLLER_SCROLLABLE: MessageScrollerScrollable = {
  start: false,
  end: false,
};

export const EMPTY_VISIBLE_MESSAGE_IDS: string[] = [];

export const EMPTY_MESSAGE_SCROLLER_VISIBILITY_STATE: MessageScrollerVisibilityState = {
  currentAnchorId: null,
  visibleMessageIds: EMPTY_VISIBLE_MESSAGE_IDS,
};
